# ============================================================
# INTEGER/NIBBLE -> GF(16)
# ============================================================

def int_to_gf16(c):

    c = int(c) & _sage_const_0xF 

    value = F(_sage_const_0 )

    for bit in range(_sage_const_4 ):

        if (c >> bit) & _sage_const_1 :
            value += a**bit

    return value


# ============================================================
# PARSING GF(16) EQUATIONS
#
# Supports:
#
#   F(3)*x_0_0
#
#   F(3)*x_0_0*x_1_2
#
#   F(3)*x_0_0^2
#
#   x_0_0*x_1_2
#
#   F(7)
#
#   7
#
# Equations:
#
#   lhs == rhs
#
# or
#
#   lhs = rhs
#
# ============================================================

VAR_RE = re.compile(
    r"^x_(\d+)_(\d+)(?:\^(\d+))?$"
)

COEFF_RE = re.compile(
    r"^F\(\s*(\d+)\s*\)$"
)

EQ_PREFIX_RE = re.compile(
    r"^\s*Eq\s+\d+\s*:\s*",
    re.IGNORECASE
)


def parse_variable_factor(text):

    m = VAR_RE.fullmatch(text.strip())

    if not m:
        raise ValueError(
            "Invalid variable factor: %r"
            % text
        )

    k = int(m.group(_sage_const_1 ))
    j = int(m.group(_sage_const_2 ))

    exponent = (
        int(m.group(_sage_const_3 ))
        if m.group(_sage_const_3 )
        else _sage_const_1 
    )

    if not (_sage_const_0  <= k < v):
        raise ValueError(
            "Invalid row index: %d"
            % k
        )

    if not (_sage_const_0  <= j < o):
        raise ValueError(
            "Invalid column index: %d"
            % j
        )

    if exponent < _sage_const_1 :
        raise ValueError(
            "Invalid exponent: %d"
            % exponent
        )

    return (
        gf_var_map[(k, j)],
        exponent
    )


def parse_term(term):
    """
    Examples:

        F(5)*x_0_0

        F(5)*x_0_0*x_3_2

        F(5)*x_0_0^2

        x_0_0*x_3_2

        F(5)

        5

    Returns a Sage polynomial in R.
    """

    term = term.strip()

    if not term:
        return R(_sage_const_0 )

    factors = [
        x.strip()
        for x in term.split("*")
        if x.strip()
    ]

    coeff = F(_sage_const_1 )

    variable_factors = []

    for factor in factors:

        # ----------------------------------------
        # F(c)
        # ----------------------------------------

        m = COEFF_RE.fullmatch(factor)

        if m:

            coeff *= int_to_gf16(
                int(m.group(_sage_const_1 ))
            )

            continue

        # ----------------------------------------
        # Bare integer
        # ----------------------------------------

        if factor.isdigit():

            coeff *= int_to_gf16(
                int(factor)
            )

            continue

        # ----------------------------------------
        # Variable
        # ----------------------------------------

        variable, exponent = (
            parse_variable_factor(factor)
        )

        variable_factors.append(
            (variable, exponent)
        )

    result = R(coeff)

    for variable, exponent in variable_factors:

        result *= variable**exponent

    return result


def parse_side(side):

    side = side.strip()

    if not side:
        return R(_sage_const_0 )

    result = R(_sage_const_0 )

    for raw_term in side.split("+"):

        term = raw_term.strip()

        if not term:
            continue

        result += parse_term(term)

    return result


def parse_equation(line):

    line = line.strip()

    line = EQ_PREFIX_RE.sub(
        "",
        line,
        count=_sage_const_1 
    )

    if "==" in line:

        lhs_text, rhs_text = (
            line.split("==", _sage_const_1 )
        )

    elif "=" in line:

        lhs_text, rhs_text = (
            line.split("=", _sage_const_1 )
        )

    else:

        raise ValueError(
            "Equation has no '=' or '==': %s"
            % line
        )

    lhs = parse_side(lhs_text)

    rhs = parse_side(rhs_text)

    # characteristic 2:
    #
    # lhs = rhs
    #
    # becomes
    #
    # lhs + rhs = 0

    return lhs + rhs


