# ============================================================
# GF(16) -> GF(2) BIT BLAST
# ============================================================

def gf2m_system_to_gf2(system):

    R_ext = system[_sage_const_0 ].parent()

    F_ext = R_ext.base_ring()

    m = F_ext.degree()

    vars_ext = list(
        R_ext.gens()
    )

    n = len(vars_ext)

    modulus = F_ext.modulus()

    modulus_coeffs = list(
        modulus.list()
    )

    # ========================================================
    # BOOLEAN VARIABLES
    #
    # x_i_j ->
    #
    #   x_i_j_b0
    #   x_i_j_b1
    #   x_i_j_b2
    #   x_i_j_b3
    # ========================================================

    bool_names = []

    for var in vars_ext:

        for bit in range(m):

            bool_names.append(
                "%s_b%d"
                %
                (
                    str(var),
                    bit
                )
            )

    B = BooleanPolynomialRing(
        n * m,
        names=bool_names
    )

    Bvars = list(
        B.gens()
    )

    var_bits = {}

    index = _sage_const_0 

    for var in vars_ext:

        var_bits[var] = list(
            Bvars[
                index:
                index + m
            ]
        )

        index += m


    # ========================================================
    # FIELD ELEMENT -> BASIS BITS
    # ========================================================

    def field_element_to_bits(c):

        c = F_ext(c)

        poly = c.polynomial()

        coeffs = list(
            poly.list()
        )

        coeffs += (
            [_sage_const_0 ]
            *
            (m - len(coeffs))
        )

        return [

            B(
                int(coeffs[i])
            )

            for i in range(m)

        ]


    # ========================================================
    # SYMBOLIC GF(16) MULTIPLICATION
    #
    # This is what allows quadratic terms.
    #
    # If:
    #
    #   X = x0 + x1*a + x2*a² + x3*a³
    #
    #   Y = y0 + y1*a + y2*a² + y3*a³
    #
    # then field_mult() creates Boolean products:
    #
    #   xi*yj
    #
    # and reduces powers of a modulo:
    #
    #   a^4 + a + 1
    # ========================================================

    def field_mult(u_bits, v_bits):

        tmp = [

            B(_sage_const_0 )

            for _ in range(
                _sage_const_2  * m - _sage_const_1 
            )

        ]

        # polynomial multiplication

        for i in range(m):

            for j in range(m):

                tmp[i + j] += (
                    u_bits[i]
                    *
                    v_bits[j]
                )

        # modular reduction

        for degree in range(
            _sage_const_2  * m - _sage_const_2 ,
            m - _sage_const_1 ,
            -_sage_const_1 
        ):

            high = tmp[degree]

            if high == B(_sage_const_0 ):
                continue

            for i in range(m):

                if (
                    int(
                        modulus_coeffs[i]
                    )
                    & _sage_const_1 
                ):

                    tmp[
                        degree - m + i
                    ] += high

            tmp[degree] = B(_sage_const_0 )

        return tmp[:m]


    def multiply_by_variable_power(
        term_bits,
        variable,
        exponent
    ):

        result = list(
            term_bits
        )

        bits = var_bits[
            variable
        ]

        for _ in range(exponent):

            result = field_mult(
                result,
                bits
            )

        return result


    # ========================================================
    # CONVERT SYSTEM
    # ========================================================

    boolean_eqs = []

    print()
    print("Bit-blasting GF(16) equations...")

    for eq_index, f in enumerate(system):

        result = [

            B(_sage_const_0 )

            for _ in range(m)

        ]

        for mon in f.monomials():

            coeff = F_ext(
                f.monomial_coefficient(
                    mon
                )
            )

            term_bits = (
                field_element_to_bits(
                    coeff
                )
            )

            exponent_tuple = tuple(
                mon.exponents()[_sage_const_0 ]
            )

            for (
                var_index,
                exponent
            ) in enumerate(
                exponent_tuple
            ):

                exponent = int(exponent)

                if exponent == _sage_const_0 :
                    continue

                variable = (
                    vars_ext[var_index]
                )

                term_bits = (
                    multiply_by_variable_power(
                        term_bits,
                        variable,
                        exponent
                    )
                )

            for bit in range(m):

                result[bit] += (
                    term_bits[bit]
                )

        # One GF(16) equation ->
        # four GF(2) equations.

        for bit in range(m):

            boolean_eqs.append(
                B(result[bit])
            )

    return (
        B,
        var_bits,
        boolean_eqs
    )
